//! The song list (曲目主表): titles and per-chart levels and note counts,
//! generated by a local tool (not in the repository) into `resources/songs.json`.
//!
//! Only what recognition and the records need is kept: title (as shown in
//! game), artist (to tell same-titled songs apart), and each chart's level
//! and notes.

use std::collections::{BTreeMap, HashSet};
use std::fmt;
use std::str::FromStr;

use serde::{Deserialize, Serialize};

/// A chart slot: play style + difficulty, e.g. `SPA`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub enum Chart {
    Spb,
    Spn,
    Sph,
    Spa,
    Spl,
    Dpn,
    Dph,
    Dpa,
    Dpl,
}

impl Chart {
    pub const ALL: [Chart; 9] = [
        Chart::Spb,
        Chart::Spn,
        Chart::Sph,
        Chart::Spa,
        Chart::Spl,
        Chart::Dpn,
        Chart::Dph,
        Chart::Dpa,
        Chart::Dpl,
    ];

    pub fn key(self) -> &'static str {
        match self {
            Chart::Spb => "SPB",
            Chart::Spn => "SPN",
            Chart::Sph => "SPH",
            Chart::Spa => "SPA",
            Chart::Spl => "SPL",
            Chart::Dpn => "DPN",
            Chart::Dph => "DPH",
            Chart::Dpa => "DPA",
            Chart::Dpl => "DPL",
        }
    }
}

impl fmt::Display for Chart {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.key())
    }
}

impl FromStr for Chart {
    type Err = String;
    fn from_str(s: &str) -> Result<Self, String> {
        Chart::ALL
            .into_iter()
            .find(|c| c.key() == s)
            .ok_or_else(|| format!("unknown chart `{s}`"))
    }
}

impl Serialize for Chart {
    fn serialize<S: serde::Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
        s.serialize_str(self.key())
    }
}

impl<'de> Deserialize<'de> for Chart {
    fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        String::deserialize(d)?
            .parse()
            .map_err(serde::de::Error::custom)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub struct ChartInfo {
    pub level: u8,
    /// Total notes, when known.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub notes: Option<u32>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Song {
    /// Stable ID derived from title + artist (see [`song_id`]).
    pub id: String,
    pub title: String,
    pub artist: String,
    pub charts: BTreeMap<Chart, ChartInfo>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct SongList {
    /// Where the data came from.
    pub source: String,
    /// When it was generated (YYYY-MM-DD).
    pub generated: String,
    pub songs: Vec<Song>,
}

#[derive(Debug, thiserror::Error, PartialEq, Eq)]
pub enum SongListError {
    #[error("song list is not valid JSON: {0}")]
    Json(String),
    #[error("duplicate song id {id} ({title})")]
    DuplicateId { id: String, title: String },
    #[error("{title}: {chart} has level {level} (expected 1–12)")]
    BadLevel {
        title: String,
        chart: Chart,
        level: u8,
    },
    #[error("{0}: no charts")]
    NoCharts(String),
}

impl SongList {
    pub fn from_json(json: &str) -> Result<Self, SongListError> {
        let list: SongList =
            serde_json::from_str(json).map_err(|e| SongListError::Json(e.to_string()))?;
        list.validate()?;
        Ok(list)
    }

    pub fn validate(&self) -> Result<(), SongListError> {
        let mut ids = HashSet::new();
        for song in &self.songs {
            if !ids.insert(&song.id) {
                return Err(SongListError::DuplicateId {
                    id: song.id.clone(),
                    title: song.title.clone(),
                });
            }
            if song.charts.is_empty() {
                return Err(SongListError::NoCharts(song.title.clone()));
            }
            for (&chart, info) in &song.charts {
                if !(1..=12).contains(&info.level) {
                    return Err(SongListError::BadLevel {
                        title: song.title.clone(),
                        chart,
                        level: info.level,
                    });
                }
            }
        }
        Ok(())
    }
}

/// Stable song ID: FNV-1a 64 of `title \n artist`, as 16 hex digits.
/// Changes only if the title or artist text changes.
pub fn song_id(title: &str, artist: &str) -> String {
    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for &b in title
        .as_bytes()
        .iter()
        .chain(b"\n")
        .chain(artist.as_bytes())
    {
        h ^= u64::from(b);
        h = h.wrapping_mul(0x0000_0100_0000_01b3);
    }
    format!("{h:016x}")
}

#[cfg(test)]
mod tests {
    use super::*;

    fn song(title: &str, charts: &[(Chart, u8)]) -> Song {
        Song {
            id: song_id(title, "x"),
            title: title.to_owned(),
            artist: "x".to_owned(),
            charts: charts
                .iter()
                .map(|&(c, level)| (c, ChartInfo { level, notes: None }))
                .collect(),
        }
    }

    fn list(songs: Vec<Song>) -> SongList {
        SongList {
            source: "test".to_owned(),
            generated: "2026-11-09".to_owned(),
            songs,
        }
    }

    #[test]
    fn round_trips_and_validates() {
        let l = list(vec![song("A", &[(Chart::Spa, 12), (Chart::Dpn, 5)])]);
        let json = serde_json::to_string(&l).unwrap();
        assert!(json.contains("\"SPA\""));
        assert_eq!(SongList::from_json(&json).unwrap(), l);
    }

    #[test]
    fn rejects_bad_data() {
        assert!(matches!(
            list(vec![song("A", &[(Chart::Spa, 13)])]).validate(),
            Err(SongListError::BadLevel { .. })
        ));
        assert!(matches!(
            list(vec![
                song("A", &[(Chart::Spa, 1)]),
                song("A", &[(Chart::Spn, 1)])
            ])
            .validate(),
            Err(SongListError::DuplicateId { .. })
        ));
        assert!(matches!(
            list(vec![song("A", &[])]).validate(),
            Err(SongListError::NoCharts(_))
        ));
    }

    #[test]
    fn bundled_song_list_is_valid() {
        let json = include_str!("../../../resources/songs.json");
        let list = SongList::from_json(json).unwrap();
        assert!(list.songs.len() > 1000);
        let star = list
            .songs
            .iter()
            .find(|s| s.title == "Shooting Star" && s.artist == "ReGLOSS")
            .unwrap();
        // Matches the result screen: SP NORMAL 4, 420 notes.
        assert_eq!(
            star.charts[&Chart::Spn],
            ChartInfo {
                level: 4,
                notes: Some(420)
            }
        );
    }

    #[test]
    fn ids_are_stable_and_distinct() {
        assert_eq!(
            song_id("ALBIDA", "DJ YOSHITAKA"),
            song_id("ALBIDA", "DJ YOSHITAKA")
        );
        assert_ne!(song_id("a", "bc"), song_id("ab", "c"));
    }
}
